function Block({ data }) {
  const key = (ds, name) => (ds.series.find((s) => s.label === name) || ds.series[0] || {}).key
  const bKey = key(data.base, 'Cash balance')
  const rKey = key(data.base, 'Revenue')
  const uKey = key(data.upside, 'Cash balance')
  const dKey = key(data.downside, 'Cash balance')
  const rows = data.base.rows.map((r, i) => ({
    date: r.date,
    base: r[bKey],
    upside: data.upside.rows[i] ? data.upside.rows[i][uKey] : null,
    downside: data.downside.rows[i] ? data.downside.rows[i][dKey] : null,
  }))
  const usd = (v) => (v == null ? '–' : (v < 0 ? '-$' : '$') + Math.round(Math.abs(v) / 1000) + 'k')
  const minBase = rows.reduce((m, r) => (r.base < m.base ? r : m), rows[0] || { base: 0, date: '' })
  const last = data.base.rows[data.base.rows.length - 1] || {}
  return (
    <Col>
      <Grid columns={4} minColumnWidth={160}>
        <Stat label="Gross margin" value="~79%" />
        <Stat label="Base: lowest cash" value={usd(minBase.base) + ' · ' + minBase.date} />
        <Stat label="Base: Dec 2028 MRR" value={usd(last[rKey])} />
        <Stat label="Downside fix" value="Hire engineer at month 18" />
      </Grid>
      <Chart height={300} options={{
        data: rows,
        series: [
          { type: 'line', xKey: 'date', yKey: 'upside', yName: 'Upside' },
          { type: 'line', xKey: 'date', yKey: 'base', yName: 'Base' },
          { type: 'line', xKey: 'date', yKey: 'downside', yName: 'Downside (hire delayed)' },
        ],
      }} />
    </Col>
  )
}

