function Block({ data }) {
  const ds = (n) => (data && data[n] && Array.isArray(data[n].rows) ? data[n] : { rows: [], series: [] })
  const base = ds('base'), up = ds('upside'), down = ds('downside')
  const key = (d, name) => ((d.series || []).find((s) => s.label === name) || (d.series || [])[0] || {}).key
  const bKey = key(base, 'Cash balance'), rKey = key(base, 'Revenue'), uKey = key(up, 'Cash balance'), dKey = key(down, 'Cash balance')
  const rows = base.rows.map((r, i) => ({
    date: r.date,
    base: r[bKey],
    upside: up.rows[i] ? up.rows[i][uKey] : null,
    downside: down.rows[i] ? down.rows[i][dKey] : null,
  }))
  const usd = (v) => (v == null ? '–' : (v < 0 ? '-$' : '$') + Math.round(Math.abs(v) / 1000) + 'k')
  const minBase = rows.length ? rows.reduce((m, r) => (r.base < m.base ? r : m), rows[0]) : { base: null, date: '' }
  const last = base.rows.length ? base.rows[base.rows.length - 1] : {}
  const series = [{ type: 'line', xKey: 'date', yKey: 'base', yName: 'Base' }]
  if (up.rows.length) series.unshift({ type: 'line', xKey: 'date', yKey: 'upside', yName: 'Upside' })
  if (down.rows.length) series.push({ type: 'line', xKey: 'date', yKey: 'downside', yName: 'Downside (hire at month 18)' })
  return (
    <Col>
      <Grid columns={4} minColumnWidth={160}>
        <Stat label="Gross margin" value="~79%" />
        <Stat label="Base: lowest cash" value={usd(minBase.base) + ' · ' + minBase.date} />
        <Stat label="Base: Dec 2028 revenue / mo" value={usd(last[rKey])} />
        <Stat label="Upside: Dec 2028 cash" value="$521k" />
      </Grid>
      {rows.length ? <Chart height={300} options={{ data: rows, series }} /> : <Text>No data.</Text>}
    </Col>
  )
}

